import java.net.URLEncoder
def body = request.entity.string ?: ''
def cid = System.getenv('INTROSPECT_CLIENT_ID') ?: ''
def cs  = System.getenv('INTROSPECT_CLIENT_SECRET') ?: ''
if (cid) { request.entity.setString(body + '&client_id=' + URLEncoder.encode(cid, 'UTF-8') + '&client_secret=' + URLEncoder.encode(cs, 'UTF-8')) }
return next.handle(context, request)
